/*
 * A095343  Length of n-th string generated by a Kolakoski(7,1) rule starting
 *          with a(1)=1.
 * https://oeis.org/A095343
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = a(n-1) + 3*a(n-2) - 3*(-1)^n, a(1)=a(2)=1
 * Range:     u8 n <= 7, u16 n <= 14, u32 n <= 27, u64 n <= 54, u128 n <= 107,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    if (n <= 2) return (seq_t)1;
    seq_t prevprev = (seq_t)1; /* a(1) */
    seq_t prev     = (seq_t)1; /* a(2) */
    seq_t cur;
    for (idx_t i = 3; i <= n; ++i) {
        cur = prev + (seq_t)3 * prevprev;
        if (i & 1) {
            cur = cur + (seq_t)3;   /* odd n: add 3 */
        } else {
            cur = cur - (seq_t)3;   /* even n: subtract 3 */
        }
        prevprev = prev;
        prev = cur;
    }
    return prev;
}
